/** Find label on dashboard and set formula one column to the right (all exact matches) */
function applyFormulaByLabel(sheet, label, formula, aliases) {
  var tries = [String(label)];
  if (aliases && aliases.length) tries = tries.concat(aliases);
  for (var i = 0; i < tries.length; i++) {
    var finder = sheet
      .createTextFinder(String(tries[i]))
      .matchEntireCell(true)
      .matchCase(false);
    var cell = finder.findNext();
    if (cell) {
      do {
        sheet.getRange(cell.getRow(), cell.getColumn() + 1).setFormula(formula);
        cell = finder.findNext();
      } while (cell);
      return true;
    }
  }
  for (var j = 0; j < tries.length; j++) {
    var finder2 = sheet
      .createTextFinder(String(tries[j]))
      .matchEntireCell(false)
      .matchCase(false);
    var cell2 = finder2.findNext();
    if (cell2) {
      sheet.getRange(cell2.getRow(), cell2.getColumn() + 1).setFormula(formula);
      return true;
    }
  }
  var want = normalizeDashLabel(label);
  var aliasNorm = (aliases || []).map(normalizeDashLabel);
  var data = sheet.getDataRange().getDisplayValues();
  for (var r = 0; r < data.length; r++) {
    for (var c = 0; c < data[r].length; c++) {
      var cellText = normalizeDashLabel(data[r][c]);
      if (!cellText) continue;
      if (cellText === want || aliasNorm.indexOf(cellText) >= 0) {
        sheet.getRange(r + 1, c + 2).setFormula(formula);
        return true;
      }
    }
  }
  for (var r2 = 0; r2 < data.length; r2++) {
    for (var c2 = 0; c2 < data[r2].length; c2++) {
      var t2 = normalizeDashLabel(data[r2][c2]);
      if (!t2 || t2.length < 4) continue;
      if (t2.indexOf(want) >= 0 || want.indexOf(t2) >= 0) {
        sheet.getRange(r2 + 1, c2 + 2).setFormula(formula);
        return true;
      }
      for (var a = 0; a < aliasNorm.length; a++) {
        if (!aliasNorm[a] || aliasNorm[a].length < 4) continue;
        if (t2.indexOf(aliasNorm[a]) >= 0 || aliasNorm[a].indexOf(t2) >= 0) {
          sheet.getRange(r2 + 1, c2 + 2).setFormula(formula);
          return true;
        }
      }
    }
  }
  return false;
}

function normalizeDashLabel(s) {
  return String(s || "")
    .trim()
    .toLowerCase()
    .replace(/[^\w\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

